Goal: Implement the QROM body in pure DSL form per PRD §4. New header include/sturm/detail/lib/qram_read_dsl.hpp:

  template <std::size_t W>
  inline void lib_qram_read_qrom_dsl(const qint_t<W>* a, std::size_t n,
                                     qint_t<W>& i, qint_t<W>& b) {
      constexpr auto K = ceil_log2(n);
      qbool eq_k;
      for (std::size_t k = 0; k < n; ++k) {
          lib_qram_eq_k_compute(i, k, K, eq_k);
          WHEN(eq_k) {
              const auto val = a[k].value;
              for (std::size_t j = 0; j < W; ++j) {
                  if ((val >> j) & 1u) b.bit(j).flip();
              }
          }
          lib_qram_eq_k_uncompute(i, k, K, eq_k);
      }
  }

Classical fan over set bits of a[k] — a[k] fully classical by QROM precondition. Each b.bit(j).flip() lifts to CX controlled on eq_k via WHEN(eq_k) (B5a depth-1 invariant). No raw gate calls, no rotations.

